create type public.portal_role as enum ('main_admin', 'admin', 'student');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text unique,full_name text,student_number text unique,role public.portal_role not null default 'student',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.news_posts (id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 3 and 180),excerpt text,body text not null check(char_length(body)>=3),category text not null default 'University News' check(category in ('University News','Academic News','Research','Career Development','Events','Announcements')),is_published boolean not null default false,published_at timestamptz,created_by uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index news_posts_public_listing_idx on public.news_posts(is_published,published_at desc,created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end; $$;
create trigger profiles_set_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger news_posts_set_updated_at before update on public.news_posts for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,lower(new.email),nullif(trim(coalesce(new.raw_user_meta_data->>'full_name','')),'')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_portal_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('main_admin','admin')); $$;
create or replace function public.is_main_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='main_admin'); $$;
create or replace function public.set_portal_role(target_user uuid,new_role public.portal_role) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_main_admin() then raise exception 'Not authorised' using errcode='42501'; end if; if target_user=auth.uid() and new_role<>'main_admin' then raise exception 'Cannot remove own main administrator role' using errcode='42501'; end if; update public.profiles set role=new_role where id=target_user; if not found then raise exception 'Profile not found' using errcode='P0002'; end if; end; $$;
alter table public.profiles enable row level security; alter table public.news_posts enable row level security;
create policy "Users read own profile; staff read profiles" on public.profiles for select to authenticated using(id=auth.uid() or public.is_portal_staff());
create policy "Published news is public; staff read all news" on public.news_posts for select using(is_published=true or public.is_portal_staff());
create policy "Staff create news" on public.news_posts for insert to authenticated with check(public.is_portal_staff() and created_by=auth.uid());
create policy "Staff update news" on public.news_posts for update to authenticated using(public.is_portal_staff()) with check(public.is_portal_staff());
create policy "Staff delete news" on public.news_posts for delete to authenticated using(public.is_portal_staff());
revoke all on public.profiles from anon,authenticated; grant select on public.profiles to authenticated; grant select,insert,update,delete on public.news_posts to anon,authenticated; grant execute on function public.set_portal_role(uuid,public.portal_role) to authenticated;
